-- ----------------------------
-- Table structure for ai_rag_chunk
-- ----------------------------
DROP TABLE IF EXISTS "public"."ai_rag_chunk";
CREATE TABLE "public"."ai_rag_chunk" (
  "id" int8 NOT NULL DEFAULT nextval('ai_rag_chunk_id_seq'::regclass),
  "document_id" int8 NOT NULL,
  "chunk_index" int4 NOT NULL,
  "text" text COLLATE "pg_catalog"."default" NOT NULL,
  "token_count" int4,
  "embedding" "public"."vector",
  "embedding_model" varchar(100) COLLATE "pg_catalog"."default",
  "embedding_version" varchar(50) COLLATE "pg_catalog"."default",
  "metadata" jsonb,
  "is_active" bool NOT NULL DEFAULT true,
  "crtim" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "cruid" int8,
  "uptim" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "upuid" int8,
  "is_deleted" bool NOT NULL DEFAULT false,
  "deleted_at" timestamp(6),
  "deleted_by" int8
)
;
COMMENT ON COLUMN "public"."ai_rag_chunk"."id" IS 'Chunk唯一ID';
COMMENT ON COLUMN "public"."ai_rag_chunk"."document_id" IS '所属文档ID，关联ai_rag_document.id';
COMMENT ON COLUMN "public"."ai_rag_chunk"."chunk_index" IS 'Chunk在原始文档中的顺序，从0开始';
COMMENT ON COLUMN "public"."ai_rag_chunk"."text" IS 'Chunk文本内容，用于语义检索和大模型上下文增强';
COMMENT ON COLUMN "public"."ai_rag_chunk"."token_count" IS 'Chunk文本Token数量，用于统计文本长度及控制上下文大小';
COMMENT ON COLUMN "public"."ai_rag_chunk"."embedding" IS '文本Embedding向量，用于语义相似度检索';
COMMENT ON COLUMN "public"."ai_rag_chunk"."embedding_model" IS '生成当前向量所使用的Embedding模型名称';
COMMENT ON COLUMN "public"."ai_rag_chunk"."embedding_version" IS 'Embedding模型版本，用于向量数据版本管理';
COMMENT ON COLUMN "public"."ai_rag_chunk"."metadata" IS 'RAG元数据，用于记录文档页码、章节、标题、来源文件等信息';
COMMENT ON COLUMN "public"."ai_rag_chunk"."is_active" IS '是否参与RAG检索：true参与，false不参与';
COMMENT ON COLUMN "public"."ai_rag_chunk"."crtim" IS '创建时间';
COMMENT ON COLUMN "public"."ai_rag_chunk"."cruid" IS '创建人ID';
COMMENT ON COLUMN "public"."ai_rag_chunk"."uptim" IS '最后更新时间';
COMMENT ON COLUMN "public"."ai_rag_chunk"."upuid" IS '最后更新人ID';
COMMENT ON COLUMN "public"."ai_rag_chunk"."is_deleted" IS '是否软删除：false未删除，true已删除';
COMMENT ON COLUMN "public"."ai_rag_chunk"."deleted_at" IS '软删除时间';
COMMENT ON COLUMN "public"."ai_rag_chunk"."deleted_by" IS '执行软删除操作的用户ID';
COMMENT ON TABLE "public"."ai_rag_chunk" IS 'AI知识库RAG文档分块及向量数据表';

