INSERT INTO "public"."ai_rag_chunk" VALUES (2093619040483835906, 2093619021043236866, 0, '现代农业种植技术知识库
RAG功能测试专用
文档版本:V1.0 | 更新时间:2026-08-29
目录
01 玉米高产种植技术 05 地块土壤与水肥管理
科学选种、合理密植与全周期水肥调控方案 土壤改良措施与高效节水灌溉技术应用
02 水稻田间管理要点 06 农业机械设备使用说明
育秧、插秧及病虫害防治的关键技术节点 现代化农机操作规范与日常维护保养指南
03 常⻅农作物病虫害防治 07 农业补贴与生产政策
绿色防控技术与综合防治体系的建立 最新惠农政策解读与补贴申领流程详解
04 农资使用规范 08 果蔬采收与储存技术
化肥、农药、种子的科学选用与安全施用标准 成熟度判断标准与保鲜储存的实用技巧
01
玉米高产种植技术
