INSERT INTO "public"."ai_rag_chunk" VALUES (2093619040873906183, 2093619021043236866, 22, '5°C易加速腐烂变质。 标准化蔬菜大棚采收现场,严格把控采收时机与操作规范,确保从田间到
餐桌的新鲜品质。
RAG测试提问集
01 基础问答测试 02 表格抽取测试 03 多条件复杂查询
考察从结构化表格中提取特定信息的能 针对复合条件的综合检索与关联分析:
聚焦基础农技知识的精准问答,验证系统
力: · 华南秋玉米的播种时间、密度与深度配
对核心概念的理解:
· 提取玉米螟防治的有效药剂及安全间隔 置
· 玉米大喇叭口期施肥方案与亩用量
期 · 水稻分蘖期与孕穗期差异化水分管理策
· 植保无人机作业的⻛力阈值与药液量
· 定位稻瘟病的最佳施药窗口期 略
· 玉米种子储存的安全含水量标准
· 快速检索农药使用规范中的关键参数 · 特定气候下的作物栽培方案匹配
04 幻觉对抗测试(边界验证) 05 综合业务场景应用
验证系统在知识库边界外的诚实性,防止生成虚假信息:
结合实际业务场景的综合判断与方案输出能力:
